#!/usr/bin/env bash
#
# Generates src/ui_font_<size>.c: Inter Medium ($INTER, set by the dev shell) for
# ASCII, Latin-1 and Latin Extended-A, Romanian ș ț, typographic quotes, dashes and
# ellipsis, € ™ √ π ∆ for the keyboard's symbols; DejaVu Sans (from LVGL's sources)
# for ✓ ★ ☆; Font Awesome 7 Free Solid and Regular ($FONTAWESOME) for the icons of
# symbols.txt.
# Falls back to the color emoji (ui_emoji_<size>, emoji.c), then
# lv_font_montserrat_<size>, which only adds LVGL's symbols (LV_SYMBOL_*). Line
# height and baseline are Montserrat's, which the layouts were made for.
#
# Also src/ui_symbols.h, UI_SYMBOL_<NAME> for symbols.txt's icons, and
# src/ui_font_clock.c, the home screen's clock: only digits and colon, from Inter
# Display Light, no fallback; src/ui_font_book.c, Books' text: Literata ($LITERATA)
# at one size.
#
# Run in `nix develop` (lv_font_conv) after Buildroot extracted LVGL:
#   external/package/phone-ui/gen-fonts.sh [lvgl source dir]
#

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
lvgl="${1:-$(ls -d "$here"/../../../output/build/lvgl-[0-9]* | tail -n 1)}"

# From a copy, with relative paths: the store is read-only and the options recorded
# in the output stay free of paths.
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
cp "$INTER/Inter-Medium.ttf" "$INTER/Inter-Display-Light.ttf" \
   "$lvgl/scripts/generators/built_in_font/DejaVuSans.ttf" "$tmp"
cp "$FONTAWESOME/Font Awesome 7 Free-Solid-900.otf" "$tmp/fa-solid.otf"
cp "$FONTAWESOME/Font Awesome 7 Free-Regular-400.otf" "$tmp/fa-regular.otf"

# UTF-8 of a codepoint (\x escapes, for a C string)
utf8() {
	local cp=$1
	if [ "$cp" -lt $((0x10000)) ]; then
		printf '\\x%02X\\x%02X\\x%02X' $((0xE0 | cp >> 12)) $((0x80 | (cp >> 6 & 0x3F))) \
			$((0x80 | (cp & 0x3F)))
	else
		printf '\\x%02X\\x%02X\\x%02X\\x%02X' $((0xF0 | cp >> 18)) $((0x80 | (cp >> 12 & 0x3F))) \
			$((0x80 | (cp >> 6 & 0x3F))) $((0x80 | (cp & 0x3F)))
	fi
}

# Font Awesome's icons (symbols.txt: name, codepoint, style): their glyphs' ranges, and
# their UI_SYMBOL_* in UTF-8. Solid ones keep Font Awesome's codepoint (the private use
# area); one of LVGL's is refused: in ui_font_<size>, it would replace LVGL's symbol.
# Regular ones share Solid's codepoints, so they move to U+F0000 + theirs (the
# supplementary private use area, four bytes) and are UI_SYMBOL_<NAME>_REGULAR.
# The name is checked against the font's glyph at that codepoint (its cmap, by ttx).
solid_ranges=
regular_ranges=
ttx -q -t cmap -o "$tmp/fa-solid.ttx" "$tmp/fa-solid.otf"
ttx -q -t cmap -o "$tmp/fa-regular.ttx" "$tmp/fa-regular.otf"
header="$tmp/ui_symbols.h"
{
	echo "/* Generated by gen-fonts.sh from symbols.txt: Font Awesome icons in ui_font_<size>,"
	echo " * beyond LVGL's symbols (LV_SYMBOL_*). A label's text, as those are. */"
	echo
	echo "#ifndef PHONE_UI_UI_SYMBOLS_H"
	echo "#define PHONE_UI_UI_SYMBOLS_H"
	echo
} > "$header"
while read -r name code style; do
	cp=$((16#$code))
	if [ "$cp" -lt $((0xE000)) ] || [ "$cp" -gt $((0xF8FF)) ]; then
		echo "symbols.txt: $name: U+$code is not in the private use area" >&2
		exit 1
	fi
	macro="UI_SYMBOL_$(echo "$name" | tr 'a-z-' 'A-Z_')"
	case $style in solid | regular) ;; *)
		echo "symbols.txt: $name: style \"$style\", not solid or regular" >&2
		exit 1
	esac
	glyph=$(sed -n "s/.*<map code=\"$(printf '0x%x' "$cp")\" name=\"\([^\"]*\)\".*/\1/p" \
		"$tmp/fa-$style.ttx" | head -n 1)
	if [ "$glyph" != "$name" ]; then
		echo "symbols.txt: $name: U+$code is ${glyph:-nothing} in Font Awesome $style" >&2
		exit 1
	fi
	case $style in
	solid)
		if grep -qiF "\"$(utf8 "$cp")\"" "$lvgl/src/font/lv_symbol_def.h"; then
			echo "symbols.txt: $name: U+$code is one of LVGL's symbols" >&2
			exit 1
		fi
		solid_ranges="$solid_ranges${solid_ranges:+,}0x$code"
		;;
	regular)
		regular_ranges="$regular_ranges${regular_ranges:+,}0x$code=>0x$(printf '%X' $((0xF0000 + cp)))"
		cp=$((0xF0000 + cp))
		macro="${macro}_REGULAR"
		;;
	esac
	printf '#define %s "%s" /* %s %s, U+%X */\n' "$macro" "$(utf8 "$cp")" "$style" "$name" "$cp" >> "$header"
done < <(sed -e 's/#.*//' "$here/symbols.txt" | awk 'NF == 2 { $3 = "solid" } NF >= 2')
printf '\n#endif\n' >> "$header"
[ -n "$solid_ranges$regular_ranges" ] || { echo "symbols.txt: no icons" >&2; exit 1; }
mv "$header" "$here/src/ui_symbols.h"

# lv_font_conv wants ranges for each font it is given
fa=()
[ -z "$solid_ranges" ] || fa+=(--font fa-solid.otf -r "$solid_ranges")
[ -z "$regular_ranges" ] || fa+=(--font fa-regular.otf -r "$regular_ranges")

for size in 16 20 24 26 32 48; do
	base="$lvgl/src/font/lv_font_montserrat_$size.c"
	line_height=$(sed -n 's/^ *\.line_height = \([0-9]*\),.*/\1/p' "$base")
	base_line=$(sed -n 's/^ *\.base_line = \([0-9]*\),.*/\1/p' "$base")
	out="$here/src/ui_font_$size.c"

	(cd "$tmp" && lv_font_conv --no-compress --no-prefilter --bpp 4 --size "$size" --format lvgl \
		--font Inter-Medium.ttf -r 0x20-0x7E,0xA0-0x17F,0x218-0x21B,0x2010,0x2012-0x2015,0x2018-0x201A,0x201C-0x201E \
		-r 0x2020-0x2022,0x2026,0x2030,0x2032-0x2033,0x2039-0x203A \
		-r 0x20AC,0x2122,0x221A,0x3C0,0x2206 \
		--font DejaVuSans.ttf -r 0x2605-0x2606,0x2713 \
		"${fa[@]}" \
		--lv-include lvgl.h --lv-font-name "ui_font_$size" -o "ui_font_$size.c")
	mv "$tmp/ui_font_$size.c" "$out"

	sed -i -e "s/^\( *\.line_height = \)[0-9]*,/\1$line_height,/" \
	       -e "s/^\( *\.base_line = \)[0-9]*,/\1$base_line,/" \
	       -e "s/^\( *\.fallback = \)NULL,/\1\&ui_emoji_$size,/" \
	       -e "s|^/\*Initialize a public general font descriptor\*/|extern const lv_font_t ui_emoji_$size; /* emoji.c, falls back to Montserrat */\n\n&|" "$out"
	grep -q "fallback = &ui_emoji_$size" "$out" || { echo "$out: no fallback" >&2; exit 1; }
done

# The clock: big, so only what "%H:%M" prints.
(cd "$tmp" && lv_font_conv --no-compress --no-prefilter --bpp 4 --size 160 --format lvgl \
	--font Inter-Display-Light.ttf -r 0x30-0x3A \
	--lv-include lvgl.h --lv-font-name ui_font_clock -o ui_font_clock.c)
mv "$tmp/ui_font_clock.c" "$here/src/ui_font_clock.c"

# Books' text: Literata Regular at one size (28 px: its x-height 8% above Inter's at
# 24, the browser's body text), the text's characters only. Its own line height
# (Literata's, generous for reading); Inter at 26 for what it lacks.
cp "$LITERATA/Literata-Regular.ttf" "$tmp"
(cd "$tmp" && lv_font_conv --no-compress --no-prefilter --bpp 4 --size 28 --format lvgl \
	--font Literata-Regular.ttf -r 0x20-0x7E,0xA0-0x17F,0x218-0x21B,0x2010,0x2012-0x2015,0x2018-0x201A,0x201C-0x201E \
	-r 0x2020-0x2022,0x2026,0x2030,0x2032-0x2033,0x2039-0x203A,0x20AC,0x2122 \
	--lv-include lvgl.h --lv-font-name ui_font_book -o ui_font_book.c)
sed -i -e "s/^\( *\.fallback = \)NULL,/\1\&ui_font_26,/" \
       -e "s|^/\*Initialize a public general font descriptor\*/|extern const lv_font_t ui_font_26;\n\n&|" "$tmp/ui_font_book.c"
grep -q "fallback = &ui_font_26" "$tmp/ui_font_book.c" || { echo "ui_font_book.c: no fallback" >&2; exit 1; }
mv "$tmp/ui_font_book.c" "$here/src/ui_font_book.c"
